/**
 * TOKENIZER-LLAMA3 UNIT TESTS — pins the byte-level BPE pipeline running the
 * Llama-3 tokenizer (src/zero-tvm/tokenizer-bpe.ts) and the Llama-3 chat
 * template (buildLlama3ChatPrompt) against mlx_lm's own tokenizer.
 *
 * Fully offline: fixtures-llama3.json was generated by
 * scripts/gen-tokenizer-fixtures-llama.py with mlx_lm loading the exact
 * tokenizer the app ships (mlx-community/Llama-3.2-1B-Instruct-4bit), and
 * tokenizer-llama3.json is a committed (minified, field-complete) copy of
 * that repo's tokenizer.json. The template fixtures are
 * apply_chat_template(add_generation_prompt=True) TOKEN ids with the
 * template's date pinned — the same contract the chat page must satisfy.
 *
 * What Llama-3 exercises that Qwen3 does not:
 *   - the Split regex comes from the JSON (\p{N}{1,3} digit runs, not \p{N})
 *   - normalizer: null (no NFC folding)
 *   - header-style chat template with the always-on date system block
 */

import { readFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { dirname, resolve } from 'node:path'
import { describe, expect, test } from 'vitest'

import {
  buildLlama3ChatPrompt,
  createByteLevelTokenizer,
  llama3DateString,
} from '../../src/zero-tvm/tokenizer-bpe.js'
import type { ByteLevelTokenizerJSON } from '../../src/zero-tvm/tokenizer-bpe.js'

const HERE = dirname(fileURLToPath(import.meta.url))

interface Fixtures {
  cases: Array<{ text: string; ids: number[]; decoded: string }>
  templates: Array<{
    messages: Array<{ role: 'system' | 'user' | 'assistant'; content: string }>
    date_string: string
    ids: number[]
  }>
}

const fixtures: Fixtures = JSON.parse(readFileSync(resolve(HERE, 'fixtures-llama3.json'), 'utf8'))
const tokenizerJson: ByteLevelTokenizerJSON = JSON.parse(
  readFileSync(resolve(HERE, 'tokenizer-llama3.json'), 'utf8'),
)
const tok = createByteLevelTokenizer(tokenizerJson)

const label = (text: string) =>
  JSON.stringify(text.length > 48 ? text.slice(0, 48) + '…' : text)

describe('encode() matches mlx_lm', () => {
  for (const { text, ids } of fixtures.cases) {
    test(label(text), () => {
      expect(tok.encode(text)).toEqual(ids)
    })
  }
})

describe('decode() matches mlx_lm', () => {
  for (const { text, ids, decoded } of fixtures.cases) {
    test(label(text), () => {
      expect(tok.decode(ids)).toBe(decoded)
    })
  }
})

describe('buildLlama3ChatPrompt is token-exact vs apply_chat_template', () => {
  fixtures.templates.forEach((t, i) => {
    test(`template fixture ${i} (${t.messages.map((m) => m.role).join('+')})`, () => {
      const ids = buildLlama3ChatPrompt(t.messages, tok, { dateString: t.date_string })
      expect(ids).toEqual(t.ids)
    })
  })

  test('default date renders strftime "%d %b %Y" (zero-padded day)', () => {
    expect(llama3DateString(new Date(2026, 7, 6))).toBe('06 Aug 2026')
    expect(llama3DateString(new Date(2024, 0, 31))).toBe('31 Jan 2024')
  })
})

describe('llama-3 pipeline specifics', () => {
  test('eos/bos/stop ids resolve to the Llama specials', () => {
    expect(tok.eosId).toBe(128009)  // <|eot_id|>
    expect(tok.bosId).toBe(128000)  // <|begin_of_text|>
    expect(tok.stopIds).toEqual([128009, 128001])  // <|eot_id|>, <|end_of_text|>
  })

  test('specials encode to single ids and strip in decode', () => {
    expect(tok.encode('<|begin_of_text|>')).toEqual([128000])
    expect(tok.encode('<|eot_id|>')).toEqual([128009])
    expect(tok.decode([128009])).toBe('')
  })

  test('\\p{N}{1,3} splits digit runs of up to 3 (not single digits)', () => {
    // "1234567890" pre-tokenizes as 123|456|789|0 — 4 pieces, each a single
    // BPE token in the Llama vocab. Qwen3's \p{N} would make 10.
    expect(tok.encode('1234567890')).toHaveLength(4)
  })

  test('no normalizer: decomposed accents are NOT folded to NFC', () => {
    const decomposed = 'cafe\u0301'   // e + combining acute
    const composed = 'caf\u00E9'       // precomposed é
    expect(tok.encode(decomposed)).not.toEqual(tok.encode(composed))
    expect(tok.decode(tok.encode(decomposed))).toBe(decomposed)
  })
})
